"""Exact checks supporting cote138 scans1–45; finite tests are not proofs at all levels."""
import json,itertools,math
from fractions import Fraction as F
from pathlib import Path
import sympy as s
out={};z=s.symbols('z')
g=27*z**2*(z-1)**2/(4*(z*z-z+1)**3)
P=4*(z*z-z+1)**3-27*z*z*(z-1)**2
out['C01_quotient']={'g':str(g),'g(1-z)-g':str(s.factor(g.subs(z,1-z)-g)),'g(1/z)-g':str(s.factor(g.subs(z,1/z)-g)),'derivative':str(s.factor(s.diff(g,z))),'factorization':str(s.factor(P)),'correct_identity_residual':str(s.expand(P-(z+1)**2*(2*z-1)**2*(z-2)**2)),'literal_missing_z_residual':str(s.factor(P-((z+1)*(2*z*z-5+2))**2)),'fibres':{'0':'0,1,infinity each e=2','1':'-1,1/2,2 each e=2','infinity':'roots of z^2-z+1 each e=3'},'Riemann_Hurwitz_ramification_sum':3+3+4}
# D8 elements r^a s^b. H=<r^2> central; S=<s> is a section over its quotient image.
def dm(x,y):return ((x[0]+(-1)**x[1]*y[0])%4,(x[1]+y[1])%2)
def di(x):return next(y for y in itertools.product(range(4),range(2)) if dm(x,y)==(0,0) and dm(y,x)==(0,0))
r=(1,0); t=(0,1);H={(0,0),(2,0)};sect={(0,0),(0,1)}
conj=dm(dm(r,t),di(r));assert conj not in sect
out['C02_normality']={'H':sorted(H),'section_image':sorted(sect),'section_centralizes_H':all(dm(x,h)==dm(h,x) for x in sect for h in H),'r_s_r_inverse':conj,'normal':False,'quotient':'D8/H=V4; image of S is an order-two normal subgroup of V4','absolute_Galois_pullback':'Pull back D8->V4 along G_Q->Gal(Q(sqrt(2),sqrt(3))/Q). The preimage of the section image is an open normal index-two subgroup, and the same conjugation refutes normality.'}
# Explicit geometric alternative: a rational punctured line with full geometric automorphism C3.
def canon(a,b,c): # sends a,b,c to0,1,infinity
    return (b-c, -(b-c)*a, b-a, -(b-a)*c)
def mul(A,B):return (A[0]*B[0]+A[1]*B[2],A[0]*B[1]+A[1]*B[3],A[2]*B[0]+A[3]*B[2],A[2]*B[1]+A[3]*B[3])
def inv(A):return (A[3],-A[1],-A[2],A[0])
def norm(A):
    v=next(x for x in A if x);return tuple(x/v for x in A)
def app(A,x):
    den=A[2]*x+A[3]
    return None if den==0 else (A[0]*x+A[1])/den
S={F(2),F(-1),F(1,2),F(3),F(-1,2),F(2,3),F(5),F(-1,4),F(4,5)}
base=tuple(sorted(S))[:3];A0=canon(*base);autos=set()
for dst in itertools.permutations(S,3):
    A=norm(mul(inv(canon(*dst)),A0))
    if {app(A,x) for x in S}==S:autos.add(A)
assert len(autos)==3
out['C03_geometric_counterexample']={'punctures':[str(x) for x in sorted(S)],'fixed_source_triple':[str(x) for x in base],'candidate_count':math.perm(len(S),3),'exhaustiveness_proof':'Every automorphism of the punctured smooth projective line extends uniquely to P1 and permutes S. Images of a fixed ordered triple determine a unique Mobius transformation. Because all source and image points are rational, every candidate has rational coefficients. All 9*8*7=504 ordered image triples are enumerated with exact fractions; retain precisely the candidates mapping S to itself. Thus this checks the full geometric automorphism group, not merely a subgroup found by searching.','geometric_automorphism_matrices':[[str(x) for x in A] for A in sorted(autos)],'order':len(autos),'group':'C3 generated by z->1/(1-z), all automorphisms defined over Q','construction':'X=P1_Qbar minus this nine-point set, Xprime=X (identity cover). Semilinear group C3 x G_Q. Take Γi=G_Q(sqrt(-3)) and its quotient C3 from the splitting field of x^3-2. The graph section Γi->C3 x Γi centralizes geometric C3 but conjugation by a lift of complex conjugation reverses its C3 character, hence its image is not normal. X is connected affine, finite presentation over Qbar; geometric pair automorphisms C3 are finite; Γ=G_Q infinite; cover degree one finite; N=π1 is invariant.'}
# At level8, theta^4=sqrt2=zeta8+zeta8^-1 imposes b parity.
chi={1:1,3:-1,5:-1,7:1};pairs=[(a,b) for a in (1,3,5,7) for b in range(8) if (-1)**b==chi[a]]
def am(x,y):return (x[0]*y[0]%8,(x[1]+x[0]*y[1])%8)
assert len(pairs)==16 and all(am(x,y) in pairs for x in pairs for y in pairs)
out['C04_level8_Kummer']={'pairs':pairs,'image_order':16,'ambient_order':32,'excluded_pair':[1,1],'closure':True,'degree_proof':'X^8-2 is Eisenstein at2, so Q(theta) has degree8 and is real. Adjoining i doubles its degree. Since sqrt2=theta^4 and zeta8=(1+i)/sqrt2, Q(theta,zeta8)=Q(theta,i) has degree16. Thus all16 permitted affine pairs occur. This finite computation alone does not prove the full tower has index2; the full-tower conclusion uses LMS2014 Theorem2.9.'}
out['C05_coboundaries']={'n':2,'mu2':['1','-1'],'all_Galois_coboundaries':['1'],'kernel_Z1_to_H1_order':1,'kernel_of_projection_H1_plus_Z2_order':2,'conclusion':'Not isomorphic as extensions over the fixed H1 quotient.','inverse_limit_proof':'T=Zhat(1) is torsion-free, so its continuous cocycle group Z1 is pointwise torsion-free. In the Kummer completion H1, the compatible class of -1 is nonzero and has order two. The invariant T^G_Q is zero since complex conjugation acts as -1. Consequently B1 is T and 0->T->Z1->H1->0 cannot split even as abstract abelian groups: a splitting would inject this nonzero torsion class into torsion-free Z1. The inverse-limit identification uses the finite invariant Mittag-Leffler condition along the factorial cofinal subsystem, not finite numerical sampling.'}
out['C06_completion_examples']={'all_ones_mod2_finite_support':False,'factorial_tuple_moduli':{str(n):{'tail_zero_after_index':n,'residues_i_1_to_n':[math.factorial(i)%n for i in range(1,n+1)]} for n in (2,3,4,6,12)},'proof':'For every fixed n, n divides i! for all i>=n. Compatible finitely supported residue tuples determine and are determined by a product tuple finite modulo each n. Finite tests illustrate this proof; no unrestricted product identity is claimed.'}
n=s.symbols('n',integer=True,positive=True)
out['C07_Fermat_counts']={'degree':'n^2','branch_points_per_value':'n','ramification_index':'n','RH_residual':str(s.simplify(2*((n-1)*(n-2)/2)-2-(-2*n*n+3*n*(n-1)))),'Euler_residual':str(s.simplify(3*n-3*n*n+2*n*n-(2-(n-1)*(n-2)))),'genus_values':{str(k):(k-1)*(k-2)//2 for k in [1,2,3,4,6,12]},'punctured_Fermat_cubic_rank':1+9*(2-1),'proper_cubic_abelian_rank':2,'punctures_cubic':9}
# F2 coordinate quotient, permuting labels realizes GL2(F2).
def quotient(v,p):return ((v[0]-v[2])%p,(v[1]-v[2])%p)
perms=list(itertools.permutations(range(3)))
mat2=[]
for q in perms:
    cols=[quotient(tuple(v[q[i]] for i in range(3)),2) for v in [(1,0,0),(0,1,0)]]
    mat2.append(tuple(cols))
assert len(set(mat2))==6
out['C08_mod2_action']={'permutation_matrices_columns':mat2,'distinct':6,'nonzero_classes':[(1,0),(0,1),(1,1)],'cyclotomic_mod2':'All units mod2 are1, so G_Q action is trivial.'}
A=s.Matrix([[0,-1],[1,-1]]);B=s.Matrix([[0,1],[1,0]])
fixed=[(a,b) for a in range(3) for b in range(3) if tuple(int(x)%3 for x in (A-s.eye(2))*s.Matrix([a,b]))==(0,0)]
lines={frozenset({(a,b),((2*a)%3,(2*b)%3)}) for a,b in itertools.product(range(3),repeat=2) if (a,b)!=(0,0)}
invar=[sorted(L) for L in lines if all(tuple(int(x)%3 for x in A*s.Matrix(v)) in L for v in L)]
out['C09_mod3_line']={'A':str(A),'charpoly':str(A.charpoly().as_expr()),'fixed_vectors':fixed,'invariant_lines':invar,'number_invariant_lines':len(invar),'transposition_on_generator':list(B*s.Matrix([1,-1])),'sign_character':'sgn(s)*chi3(sigma)'}
assert len(invar)==1
# Cone counts modulo3n, quotient by scalar translations.
cone_counts={}
for n0 in range(1,8):
    triples=[v for v in itertools.product(range(3*n0),repeat=3) if len({x%3 for x in v})==3]
    reps={tuple((x-v[2])%(3*n0) for x in v) for v in triples}
    cone_counts[str(n0)]={'cone':len(triples),'quotient':len(reps),'expected':2*n0*n0}
    assert len(triples)==6*n0**3 and len(reps)==2*n0*n0
out['C10_cone_counts']=cone_counts
# Branch fibre at finite level; M_m acts on a mod2 coset in M_2m through doubling.
branch={}
for m in (2,3,4,5,8):
    coset={(x,y) for x in range(2*m) for y in range(2*m) if x%2==1 and y%2==0}
    quotient_reps={y for x,y in coset}
    stab=[(a,b) for a in range(m) for b in range(m) if (2*b)%(2*m)==0]
    branch[str(m)]={'coset_size':len(coset),'quotient_by_2Zi_size':len(quotient_reps),'stabilizer_size':len(stab),'ordinary_e1_preserves_coset':False,'doubled_action_preserves':all(((x+2*a)%(2*m),(y+2*b)%(2*m)) in coset for x,y in coset for a,b in itertools.product(range(m),repeat=2))}
out['C11_scaled_branch_cosets']=branch
# Exact coordinate residues under j^2+j+1=0.
j=s.symbols('j');red=lambda f:str(s.rem(s.expand(f),j*j+j+1,j))
out['C12_transport_coordinates']={'correct_exp_pm_pi_over_n_sum':str(-s.Rational(1,2)-s.Rational(1,2)+1),'literal_scan38_zeta_sum':red(s.Rational(1,2)*(j*j+j)+1),'literal_theta_not_inverse_with_zeta_sum':red(2*(j*j+j)+1),'theta_not_inverse_with_correct_midpoint_eta_sum':-3,'correct_origin_nth_powers':'(jbar,j,1), t=-jbar','root_system_relation':'eta_n^2=zeta_n^3; eta_n=exp(pi*i/n), zeta_n=exp(2*pi*i/(3n))'}
out['C13_prime_characteristics']={'p2':'1/2 and -1/2 are undefined; -1=1 so branch sign torsor degenerates.','p3':'z^2-z+1=(z+1)^2 mod3; primitive third roots and the two distinct centres collapse.','Fermat_core':'For p not dividing n, partial derivatives n*x^(n-1),n*y^(n-1),n*z^(n-1) do not vanish simultaneously in projective space.'}
# Affine action on F2^2.
vs=list(itertools.product(range(2),repeat=2));aff=[]
for cols in set(mat2):
    for shift in vs:
        perm=tuple(vs.index(((cols[0][0]*x+cols[1][0]*y+shift[0])%2,(cols[0][1]*x+cols[1][1]*y+shift[1])%2)) for x,y in vs)
        aff.append(perm)
assert len(set(aff))==24
# Face poset of2-digon sphere: each of2 vertices incident with2 edges, each edge with2 faces.
vertices=[('v',i) for i in range(2)]+[('e',i) for i in range(2)]+[('f',i) for i in range(2)]
triangles=[(('v',v),('e',e),('f',f)) for v,e,f in itertools.product(range(2),repeat=3)]
edges={tuple(sorted(e)) for tri in triangles for e in itertools.combinations(tri,2)}
out['C14_octahedron']={'affine_group_order':len(set(aff)),'all_permutations_of_4':len(set(aff))==math.factorial(4),'barycentric_bihedron':{'V':len(vertices),'E':len(edges),'F':len(triangles),'all_edges_join_distinct_types':all(a[0]!=b[0] for a,b in edges),'graph':'K_2,2,2'},'double_quotients':[{'line':v,'killed_inertia_type':i,'remaining_branch_types':[j for j in range(3) if j!=i]} for i,v in enumerate([(1,0),(0,1),(1,1)])]}
out['C15_basic_scope_counterexamples']={'Aut_P1':'t->t+2 is invertible with inverse t->t-2 and sends0,1,infinity to2,3,infinity.','Aut_Gm':'t->1/t is an automorphism, inverse itself, interchanges0,infinity, not a scaling.','C2_Q_points':'If rational x^2+y^2+z^2=0, each real square is nonnegative and all coordinates are0, forbidden in projective space.','K0':'{z:z^n=0} has one point and cannot be a free mu_n-torsor for n>1.','projective_quotient':'For n=1, pairs(y,z) with y+z=0 modulo mu_1 are infinitely many; projective fibre is one point. Divide nonzero triples by Gm before using y/z.'}
# Finite cocycle and inversion identity, symbolic composition.
a,b,c,d,x=s.symbols('a b c d x')
out['C16_affine_law']={'composition':str(s.expand(a*(c*x+d)+b)),'product':'(a,b)(c,d)=(ac,b+ad)','dual_action':'x->a*x-b','inverse_transport_check':str(s.expand(-(a*(-x)+b)-(a*x-b))),'cofinal_limits':'(u_3n)^3=u_n and v_3n^3=v_n under inverse-system compatibility.'}
out['C17_eight_points']={'real':['0','1','infinity','-1','1/2','2'],'nonreal_polynomial':'z^2-z+1','discriminant':-3,'total':8}
P=Path(__file__).resolve().parents[1]/'outputs/computations.json';P.write_text(json.dumps(out,ensure_ascii=False,indent=2,default=str)+'\n')
print(json.dumps(out,ensure_ascii=False,indent=2,default=str))
